1→import { createHash } from 'node:crypto';
2→import { createRequire } from 'node:module';
3→import { existsSync, lstatSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
4→import { extname, isAbsolute, join, relative, resolve, sep } from 'node:path';
5→import { Lang, parse } from '@ast-grep/napi';
6→
7→const require = createRequire(import.meta.url);
8→const VERSION = require('@ast-grep/napi/package.json').version;
9→const LANG = { '.js': Lang.JavaScript, '.mjs': Lang.JavaScript, '.cjs': Lang.JavaScript, '.jsx': Lang.JavaScript, '.ts': Lang.TypeScript, '.mts': Lang.TypeScript, '.cts': Lang.TypeScript, '.tsx': Lang.Tsx };
10→const FUNCTION_KINDS = new Set(['function_declaration', 'generator_function_declaration', 'method_definition', 'function_expression', 'arrow_function']);
11→function sha(value) { return createHash('sha256').update(value).digest('hex'); }
12→function typed(message, code) { return Object.assign(new Error(message), { code }); }
13→function abort(ctx) { if (ctx?.signal?.aborted) throw typed('CPG build cancelled', 'cancelled'); }
14→function range(node) { const r = node.range(); return { start: { line: r.start.line + 1, column: r.start.column + 1 }, end: { line: r.end.line + 1, column: r.end.column + 1 } }; }
15→function id(type, node) { const r = node.range(); return `${type}:${r.start.index}:${r.end.index}`; }
16→function fingerprint(node) {
17→  if (node.kind() === 'comment' || node.kind() === ';') return '';
18→  const children = node.children().filter((child) => child.kind() !== 'comment');
19→  if (children.length === 0) return `${node.kind()}:${JSON.stringify(node.text())}`;
20→  return `${node.kind()}(${children.map(fingerprint).filter(Boolean).join(',')})`;
21→}
22→function firstName(node) {
23→  try { const value = node.field('name'); if (value) return value.text(); } catch { /* grammar variance */ }
24→  return node.children().find((child) => ['identifier', 'property_identifier'].includes(child.kind()))?.text() ?? null;
25→}
26→function booleanLiteral(node) {
27→  if (!node) return null;
28→  if (node.kind() === 'true' || node.kind() === 'false') return node.kind();
29→  if (node.kind() !== 'parenthesized_expression') return null;
30→  const children = node.children().filter((child) => child.isNamed() && child.kind() !== 'comment');
31→  return children.length === 1 ? booleanLiteral(children[0]) : null;
32→}
33→function safe(root, path) {
34→  if (!path || isAbsolute(path)) throw typed('relative CPG source path required', 'path_escape');
35→  const rr = realpathSync(root); const candidate = resolve(rr, path); const rel = relative(rr, candidate);
36→  if (rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)) throw typed('CPG source escapes root', 'path_escape');
37→  let real; try { real = realpathSync(candidate); } catch { throw typed('CPG source unavailable', 'invalid_source'); }
38→  if (real !== rr && !real.startsWith(`${rr}${sep}`)) throw typed('CPG symlink escapes root', 'path_escape');
39→  if (!lstatSync(real).isFile()) throw typed('CPG source is not a file', 'invalid_source');
40→  return real;
41→}
42→function bounded(items, tokens) { const out = []; for (const item of items) { if (Buffer.byteLength(JSON.stringify([...out, item])) > tokens * 4) break; out.push(item); } return out; }
43→
44→export class AtlasCpgSlice {
45→  constructor(opts = {}) {
46→    if (!opts.artifactRoot) throw new TypeError('CPG artifactRoot required');
47→    for (const key of ['maxSourceBytes', 'maxArtifactBytes', 'maxReachDefPairs']) if (!Number.isSafeInteger(opts[key]) || opts[key] <= 0) throw new TypeError(`${key} must be deployment-derived`);
48→    this.artifactRoot = opts.artifactRoot; this.maxSourceBytes = opts.maxSourceBytes; this.maxArtifactBytes = opts.maxArtifactBytes; this.maxReachDefPairs = opts.maxReachDefPairs; this.now = opts.now ?? Date.now; this.record = opts.record ?? null;
49→    mkdirSync(this.artifactRoot, { recursive: true, mode: 0o700 });
50→  }
51→  card() { return Object.freeze({ name: 'atlas-cpg-slice', version: '0.3.0', underlying: [`@ast-grep/napi@${VERSION}`], ops: { 'cpg.build': { deterministic: true, latency_class: 'interactive', side_effects: 'writes_content_addressed_artifact', reverifiable: true } }, languages: ['javascript', 'typescript', 'tsx'], limitations: ['single-file JS/TS-family slice', 'bounded CFG may-reaching definitions, not SSA/must-def/full PDG', 'value flow covers direct identifier/call assignment and direct call arguments', 'literal-only dead-branch pruning; no general path-condition solving', 'no shadowing-aware bindings/aliases/heap/implicit flow/interprocedural dataflow/dynamic dispatch', 'only braced if control is expanded; unsupported control constructs are atomic', 'standalone bare blocks are not CFG spine nodes'] }); }
52→
53→  async invoke(op, args, ctx) {
54→    if (op !== 'cpg.build') throw typed('unsupported CPG operation', 'unsupported_op');
55→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required');
56→    abort(ctx); const language = LANG[extname(args?.path ?? '').toLowerCase()]; if (!language) throw typed('unsupported CPG language', 'unsupported_language');
57→    const file = safe(ctx.root, args.path); const bytes = readFileSync(file); if (bytes.includes(0) || bytes.length > this.maxSourceBytes) throw typed('CPG source exceeds budget or is binary', 'invalid_source');
58→    let source; try { source = new TextDecoder('utf-8', { fatal: true }).decode(bytes); } catch { throw typed('CPG source is invalid UTF-8', 'invalid_source'); }
59→    const sourceDigest = sha(bytes); const started = this.now(); this.record?.({ kind: 'capability.op.started', actor: ctx.actor ?? 'orchestrator', op, sourceDigest });
60→    const root = parse(language, source).root(); const nodes = []; const edges = []; const errors = []; const functions = []; const occurrences = []; const calls = []; const statements = []; const blockStatements = new Map(); const pendingAssignments = []; const pendingArguments = [];
61→    const nodeId = (type, node) => `${sourceDigest}:${id(type, node)}`;
62→    const edgeIds = new Set(); const edge = (type, from, to) => { if (!from || !to) return; const edgeId = sha(`${type}\0${from}\0${to}`); if (edgeIds.has(edgeId)) return; edgeIds.add(edgeId); edges.push({ id: edgeId, type, from, to }); };
63→    function visit(node, state = { fn: null, block: null, parent: null, statement: null }) {
64→      abort(ctx); const kind = node.kind(); if (kind === 'ERROR') errors.push(range(node));
65→      let fn = state.fn; let block = state.block; let statement = state.statement;
66→      if (FUNCTION_KINDS.has(kind)) {
67→        const name = (state.parent?.kind() === 'variable_declarator' ? firstName(state.parent) : null) ?? firstName(node) ?? '<anonymous>';
68→        fn = nodeId('function', node); const entry = `${fn}:entry`; const exit = `${fn}:exit`;
69→        nodes.push({ id: fn, type: 'function', kind, name, path: args.path, range: range(node) }, { id: entry, type: 'entry', function: fn }, { id: exit, type: 'exit', function: fn });
70→        functions.push({ id: fn, name, node, entry, exit, bodyBlock: null }); statement = null;
71→      }
72→      if (kind === 'statement_block') { block = nodeId('block', node); const owner = functions.find((item) => item.id === fn); if (owner && !owner.bodyBlock) owner.bodyBlock = block; }
73→      const isStatement = kind.endsWith('_statement') || ['lexical_declaration', 'variable_declaration'].includes(kind);
74→      if (isStatement && fn) {
75→        const parentStatement = statement; const sid = nodeId('statement', node); const record = { id: sid, node, kind, fn, block, parentStatement };
76→        nodes.push({ id: sid, type: 'statement', kind, function: fn, parentStatement, path: args.path, range: range(node), textDigest: sha(node.text()), syntaxDigest: sha(fingerprint(node)) }); edge('CONTAINS', fn, sid);
77→        statements.push(record); const list = blockStatements.get(block) ?? []; list.push(record); blockStatements.set(block, list); statement = sid;
78→      }
79→      if (kind === 'identifier' && fn) {
80→        const oid = nodeId('identifier', node); const parent = state.parent; const siblings = parent?.children().filter((child) => child.isNamed()) ?? [];
81→        const definition = ['formal_parameters', 'required_parameter', 'optional_parameter'].includes(parent?.kind()) || (parent?.kind() === 'variable_declarator' && siblings[0]?.id() === node.id()) || (parent?.kind() === 'assignment_expression' && siblings[0]?.id() === node.id());
82→        nodes.push({ id: oid, type: 'identifier', name: node.text(), role: definition ? 'definition' : 'reference', function: fn, statement, path: args.path, range: range(node) }); edge('CONTAINS', fn, oid);
83→        occurrences.push({ id: oid, name: node.text(), role: definition ? 'definition' : 'reference', fn, statement, start: node.range().start.index });
84→      }
85→      if (kind === 'call_expression' && fn) {
86→        const callee = node.children().find((child) => child.isNamed()); const name = callee ? callee.text().match(/[A-Za-z_$][\w$]*$/)?.[0] ?? null : null; const cid = nodeId('call', node);
87→        nodes.push({ id: cid, type: 'call', caller: fn, statement, calleeName: name, calleeText: callee?.text() ?? null, resolved: null, candidates: [], path: args.path, range: range(node) }); edge('CONTAINS', fn, cid); calls.push({ id: cid, name, fn });
88→        let argumentsNode = null; try { argumentsNode = node.field('arguments'); } catch { /* grammar variance */ }
89→        if (argumentsNode) {
90→          for (const value of argumentsNode.children().filter((child) => child.isNamed())) if (['identifier', 'call_expression'].includes(value.kind())) pendingArguments.push({ value, call: node });
91→        }
92→      }
93→      if (['variable_declarator', 'assignment_expression'].includes(kind)) {
94→        const named = node.children().filter((child) => child.isNamed()); const target = named[0]; const value = named[1];
95→        if (target?.kind() === 'identifier' && value) {
