102→    const terminal = (item) => ['return_statement', 'throw_statement'].includes(item?.kind);
103→    const statementById = new Map(statements.map((item) => [item.id, item]));
104→    const directStatements = (list = []) => list.filter((item) => {
105→      if (!item.parentStatement) return true;
106→      return statementById.get(item.parentStatement)?.block !== item.block;
107→    }).sort((a, b) => a.node.range().start.index - b.node.range().start.index);
108→    const sequenceFor = (stmt) => directStatements(blockStatements.get(stmt.block));
109→    const functionById = new Map(functions.map((item) => [item.id, item]));
110→    const joinFor = (stmt, seen = new Set()) => {
111→      if (!stmt || seen.has(stmt.id)) return functionById.get(stmt?.fn)?.exit ?? null;
112→      seen.add(stmt.id); const list = sequenceFor(stmt); const index = list.findIndex((item) => item.id === stmt.id);
113→      if (index >= 0 && list[index + 1]) return list[index + 1].id;
